// EscrowCreateEscrowInput contains input parameters for create_escrow.
// Create and fund an escrow. `inspection_window` and `dispute_window` are ledger counts. Returns the escrow id.
type EscrowCreateEscrowInput struct {
	Buyer string `json:"buyer"`
	Seller string `json:"seller"`
	Inspector string `json:"inspector"`
	Token string `json:"token"`
	Amount int64 `json:"amount"`
	Threshold uint32 `json:"threshold"`
	InspectionWindow uint32 `json:"inspection_window"`
	DisputeWindow uint32 `json:"dispute_window"`
}

// EscrowApproveReleaseInput contains input parameters for approve_release.
// Record `signer`'s approval; releases to the seller when the threshold is met and the inspector has signed. After the inspection deadline no further approvals are accepted unless the inspector already approved.
type EscrowApproveReleaseInput struct {
	Id uint32 `json:"id"`
	Signer string `json:"signer"`
}

// EscrowRaiseDisputeInput contains input parameters for raise_dispute.
// Buyer or seller freezes release and starts the dispute window.
type EscrowRaiseDisputeInput struct {
	Id uint32 `json:"id"`
	Party string `json:"party"`
}

// EscrowResolveDisputeInput contains input parameters for resolve_dispute.
// Inspector settles a dispute (before the dispute window lapses).
type EscrowResolveDisputeInput struct {
	Id uint32 `json:"id"`
	Inspector string `json:"inspector"`
	ReleaseToSeller bool `json:"release_to_seller"`
}

// EscrowRefundInput contains input parameters for refund.
// Return funds to the buyer. Permissionless, but only valid once a deadline has lapsed: the inspection deadline with no inspector approval, or the dispute deadline of an unresolved dispute.
type EscrowRefundInput struct {
	Id uint32 `json:"id"`
}

// EscrowGetEscrowInput contains input parameters for get_escrow.
// Invokes `get_escrow` on escrow.
type EscrowGetEscrowInput struct {
	Id uint32 `json:"id"`
}

// EscrowClient defines the client interface for escrow.
type EscrowClient interface {
	CreateEscrow(ctx context.Context, input EscrowCreateEscrowInput) (uint32, error)
	ApproveRelease(ctx context.Context, input EscrowApproveReleaseInput) error
	RaiseDispute(ctx context.Context, input EscrowRaiseDisputeInput) error
	ResolveDispute(ctx context.Context, input EscrowResolveDisputeInput) error
	Refund(ctx context.Context, input EscrowRefundInput) error
	GetEscrow(ctx context.Context, input EscrowGetEscrowInput) (any, error)
}

