// ============================================================================
// Contract: state-channel
// ============================================================================

// StateChannelOpenChannelInput contains input parameters for open_channel.
// Open a new payment channel. Both parties must call this to fund their stakes. channel_id is a unique identifier (e.g., hash of (party_a, party_b, nonce))
type StateChannelOpenChannelInput struct {
	ChannelId []byte `json:"channel_id"`
	PartyA string `json:"party_a"`
	PartyB string `json:"party_b"`
	Token string `json:"token"`
	StakeA int64 `json:"stake_a"`
	StakeB int64 `json:"stake_b"`
	Caller string `json:"caller"`
}

// StateChannelCloseChannelInput contains input parameters for close_channel.
// Cooperatively close the channel with mutually signed final state. This is the gas-optimal path and settles immediately without disputes.
type StateChannelCloseChannelInput struct {
	ChannelId []byte `json:"channel_id"`
	FinalState any `json:"final_state"`
	Caller string `json:"caller"`
}

// StateChannelInitiateDisputeInput contains input parameters for initiate_dispute.
// Initiate unilateral dispute with the latest state you have. Starts a 24-hour challenge window for the counterparty to submit a newer state.
type StateChannelInitiateDisputeInput struct {
	ChannelId []byte `json:"channel_id"`
	State any `json:"state"`
	Caller string `json:"caller"`
}

// StateChannelChallengeDisputeInput contains input parameters for challenge_dispute.
// Challenge a dispute by submitting a state with a higher sequence number. If successful, the challenger proves the dispute initiator submitted stale state (fraud).
type StateChannelChallengeDisputeInput struct {
	ChannelId []byte `json:"channel_id"`
	NewerState any `json:"newer_state"`
	Caller string `json:"caller"`
}

// StateChannelFinalizeDisputeInput contains input parameters for finalize_dispute.
// Finalize the dispute after the challenge window expires. Settles balances according to the latest submitted state. If fraud was detected (challenge succeeded), slashes the dishonest party's escrow stake.
type StateChannelFinalizeDisputeInput struct {
	ChannelId []byte `json:"channel_id"`
	Caller string `json:"caller"`
}

// StateChannelInitDisputeConfigInput contains input parameters for init_dispute_config.
// One-time setup of the adjudication parameters. Until this is called the contract uses `DISPUTE_WINDOW_LEDGERS` and `DEFAULT_FRAUD_BOUNTY_BPS`.
type StateChannelInitDisputeConfigInput struct {
	Admin string `json:"admin"`
	DisputeWindowLedgers uint32 `json:"dispute_window_ledgers"`
	FraudBountyBps uint32 `json:"fraud_bounty_bps"`
}

// StateChannelUpdateDisputeConfigInput contains input parameters for update_dispute_config.
// Admin-only update of the adjudication parameters. Disputes that are already open keep the window and bounty they were opened with.
type StateChannelUpdateDisputeConfigInput struct {
	DisputeWindowLedgers uint32 `json:"dispute_window_ledgers"`
	FraudBountyBps uint32 `json:"fraud_bounty_bps"`
}

// StateChannelGetDisputeConfigInput contains input parameters for get_dispute_config.
// Invokes `get_dispute_config` on state-channel.
type StateChannelGetDisputeConfigInput struct {
}

// StateChannelRegisterSigningKeyInput contains input parameters for register_signing_key.
// Register the Ed25519 key `party` signs channel states with. Each key can be set once, before any dispute is opened, so a party cannot swap keys to repudiate states it already signed.
type StateChannelRegisterSigningKeyInput struct {
	ChannelId []byte `json:"channel_id"`
	Party string `json:"party"`
	PublicKey []byte `json:"public_key"`
}

// StateChannelGetSigningKeysInput contains input parameters for get_signing_keys.
// Invokes `get_signing_keys` on state-channel.
type StateChannelGetSigningKeysInput struct {
	ChannelId []byte `json:"channel_id"`
}

// StateChannelGetDisputeInput contains input parameters for get_dispute.
// Invokes `get_dispute` on state-channel.
type StateChannelGetDisputeInput struct {
	ChannelId []byte `json:"channel_id"`
}

// StateChannelOpenDisputeInput contains input parameters for open_dispute.
// (1) Open a dispute with the latest state `caller` holds.  `signatures` must be `[sig_a, sig_b]` over the state and is batch-verified against the registered keys. The state's balances are deliberately *not* checked here (optimistic adjudication): an invalid state can be disproven by anyone through `submit_fraud_proof`, and `resolve_dispute` never settles at an invalid state.
type StateChannelOpenDisputeInput struct {
	ChannelId []byte `json:"channel_id"`
	LatestState any `json:"latest_state"`
	Signatures [][]byte `json:"signatures"`
	Caller string `json:"caller"`
}

// StateChannelCounterDisputeInput contains input parameters for counter_dispute.
// (2) The counter-party answers an open dispute with a newer state.  Only accepted within the dispute window and only if `newer_state` has a strictly higher sequence than every submission not yet proven fraudulent.
type StateChannelCounterDisputeInput struct {
	ChannelId []byte `json:"channel_id"`
	NewerState any `json:"newer_state"`
	Signatures [][]byte `json:"signatures"`
	Caller string `json:"caller"`
}

// StateChannelSubmitFraudProofInput contains input parameters for submit_fraud_proof.
// Fraud proof: anyone other than the submitter can show that a submitted state is provably invalid and earn `fraud_bounty_bps` of the submitter's deposit. The disproven state is excluded from settlement.  The bounty is capped at what remains of the submitter's deposit, and is accounted for at settlement, so it can never be paid from the counter-party's funds or from other channels.
type StateChannelSubmitFraudProofInput struct {
	ChannelId []byte `json:"channel_id"`
	InvalidState any `json:"invalid_state"`
	Proof any `json:"proof"`
	Prover string `json:"prover"`
}

// StateChannelResolveDisputeInput contains input parameters for resolve_dispute.
// (3) After the dispute window, close the channel and settle at the highest-sequence valid submission. If no valid submission exists the original deposits are returned. Fraud bounties already paid are deducted from the fraudulent party's share. Permissionless.
type StateChannelResolveDisputeInput struct {
	ChannelId []byte `json:"channel_id"`
}

// StateChannelGetChannelInput contains input parameters for get_channel.
// Get channel info
type StateChannelGetChannelInput struct {
	ChannelId []byte `json:"channel_id"`
}

// StateChannelClient defines the client interface for state-channel.
type StateChannelClient interface {
	OpenChannel(ctx context.Context, input StateChannelOpenChannelInput) error
	CloseChannel(ctx context.Context, input StateChannelCloseChannelInput) error
	InitiateDispute(ctx context.Context, input StateChannelInitiateDisputeInput) error
	ChallengeDispute(ctx context.Context, input StateChannelChallengeDisputeInput) error
	FinalizeDispute(ctx context.Context, input StateChannelFinalizeDisputeInput) error
	InitDisputeConfig(ctx context.Context, input StateChannelInitDisputeConfigInput) error
	UpdateDisputeConfig(ctx context.Context, input StateChannelUpdateDisputeConfigInput) error
	GetDisputeConfig(ctx context.Context, input StateChannelGetDisputeConfigInput) (any, error)
	RegisterSigningKey(ctx context.Context, input StateChannelRegisterSigningKeyInput) error
	GetSigningKeys(ctx context.Context, input StateChannelGetSigningKeysInput) (any, error)
	GetDispute(ctx context.Context, input StateChannelGetDisputeInput) (any, error)
	OpenDispute(ctx context.Context, input StateChannelOpenDisputeInput) error
	CounterDispute(ctx context.Context, input StateChannelCounterDisputeInput) error
	SubmitFraudProof(ctx context.Context, input StateChannelSubmitFraudProofInput) (int64, error)
	ResolveDispute(ctx context.Context, input StateChannelResolveDisputeInput) (any, error)
	GetChannel(ctx context.Context, input StateChannelGetChannelInput) (any, error)
}

